/* @lc app=leetcode id=2617 lang=kotlin */
class Solution { fun minimumVisitedCells(grid: Array<IntArray>): Int = grid.size.let { n -> grid[0].size.let { m -> if (n == 1 && m == 1) 1 else Array(n) { r -> java.util.TreeSet((0 until m).toSet()) }.let { rows -> Array(m) { c -> java.util.TreeSet((0 until n).toSet()) }.let { cols -> IntArray(n * m) { -1 }.also { it[0] = 1 }.let { dist -> java.util.ArrayDeque<Int>().also { q -> q.add(0).also { rows[0].remove(0).also { cols[0].remove(0) } } }.let { q -> generateSequence { q.poll() }.forEach { u -> (u / m).let { r -> (u % m).let { c -> grid[r][c].let { step -> rows[r].subSet(c + 1, minOf(c + step + 1, m)).toList().forEach { nc -> (r * m + nc).let { v -> dist[v] = (dist[u] + 1).also { q.add(v).also { rows[r].remove(nc).also { cols[nc].remove(r) } } } } }.run { cols[c].subSet(r + 1, minOf(r + step + 1, n)).toList().forEach { nr -> (nr * m + c).let { v -> dist[v] = (dist[u] + 1).also { q.add(v).also { rows[nr].remove(c).also { cols[c].remove(nr) } } } } } } } } } }.run { dist[n * m - 1] } } } } } } }